'QZ_Step_Install' => '1. Instale o QZ Tray neste computador — baixe-o gratuitamente em qz.io, inicie-o e deixe-o em execução (ele fica na bandeja do sistema no Windows ou na barra de menus no macOS).',
'QZ_Step_Connect' => '2. Conecte sua impressora de etiquetas via USB e verifique se ela está instalada no sistema operacional (Windows: Configurações > Impressoras e scanners — macOS: Ajustes do Sistema > Impressoras e Scanners).',
'QZ_Step_Detect' => '3. Clique no botão ⟳ ao lado de "Nome da impressora" acima para detectar as impressoras deste computador e selecione sua impressora de etiquetas. Deixe o campo vazio para usar a impressora padrão do computador.',
'QZ_Step_Cert' => '4. Para imprimir sem a janela de permissão, baixe o certificado abaixo e copie-o para a pasta de instalação do QZ Tray, renomeado para override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Em seguida, feche o QZ Tray e inicie-o novamente.',
'QZ_Step_Test' => '5. Clique em "Imprimir etiqueta de teste" abaixo. Se o QZ Tray pedir permissão, clique em Permitir — com o certificado instalado, ele não perguntará novamente.',
'QZ_Step_Save' => '6. Clique em Enviar para salvar estas configurações. As etiquetas da página Imprimir Código de Barras passarão a ser impressas diretamente nesta impressora, sem a caixa de diálogo de impressão do navegador.',
'QZ_Setup_Note' => 'O QZ Tray é executado no computador que você está usando, então isso funciona mesmo quando o Stocky está hospedado em um servidor remoto. Todo computador que imprime etiquetas precisa ter o QZ Tray instalado.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Ativar aplicativo instalável',
'PWA_Enabled_Help' => 'Permite que os navegadores ofereçam a instalação deste aplicativo em celulares, tablets e computadores, e mantém em cache as páginas que funcionam offline. Desativar remove o convite de instalação em todos os lugares e limpa o cache na próxima visita.',
'PWA_Identity' => 'Identidade do aplicativo',
'PWA_Launch' => 'Inicialização e aparência',
'PWA_App_Name' => 'Nome do aplicativo',
'PWA_App_Name_Help' => 'Exibido no convite de instalação e na lista de aplicativos. Deixe vazio para usar o nome do aplicativo das configurações de Aparência.',
'PWA_Short_Name' => 'Nome curto',
'PWA_Short_Name_Help' => 'Exibido abaixo do ícone nas telas iniciais, onde nomes longos são cortados. Deixe vazio para usar a parte do nome do aplicativo antes do "|".',
'PWA_Description' => 'Descrição',
'PWA_Description_Help' => 'Exibida por algumas lojas de aplicativos e caixas de diálogo de instalação.',
'PWA_Start_Url' => 'Página inicial',
'PWA_Start_Url_Help' => 'A página em que o aplicativo instalado abre, como um caminho começando com "/". Use /next/pos para abrir direto no PDV.',
'PWA_Display_Mode' => 'Modo de exibição',
'PWA_Display_Mode_Help' => 'standalone oculta a barra do navegador; fullscreen também oculta a barra de status; browser abre uma aba normal.',
'PWA_Orientation' => 'Orientação',
'PWA_Theme_Color' => 'Cor do tema',
'PWA_Theme_Color_Help' => 'Colore as barras do sistema ao redor do aplicativo instalado.',
'PWA_Background_Color' => 'Fundo da tela de abertura',
'PWA_Background_Color_Help' => 'Fundo da tela de abertura exibida enquanto o aplicativo inicia.',
'PWA_Preview' => 'Pré-visualização',
'PWA_View_Manifest' => 'Ver arquivo manifest',
'PWA_Reinstall_Notice' => 'Dispositivos que já instalaram o aplicativo mantêm o nome e o ícone antigos até que ele seja desinstalado e instalado novamente.',

'Label_Render_Mode' => 'Renderização da etiqueta',
'Label_Render_Mode_Hint' => 'Como a etiqueta é desenhada. Fontes da impressora é o mais rápido e gera o código de barras mais nítido, mas imprime apenas caracteres latinos básicos na fonte da própria impressora. Imagem de pré-visualização reproduz exatamente o design da sua etiqueta — sua fonte escolhida, qualquer idioma — como fazem os softwares dedicados de etiquetas.',
'Render_Native' => 'Fontes da impressora (mais rápido)',
'Render_Raster' => 'Imagem de pré-visualização (design exato)',
'Label_Width_Mm' => 'Largura da etiqueta (mm)',
'Label_Height_Mm' => 'Altura da etiqueta (mm)',
'Label_Size_Hint' => 'O tamanho físico de um adesivo no rolo. Ele deve corresponder exatamente às etiquetas carregadas — um tamanho errado faz a impressora procurar o espaço no lugar errado, e cada etiqueta sai cada vez mais fora de posição.',
'Calibrate_Labels' => 'Calibrar etiquetas',
'Calibrate_Labels_Hint' => 'A impressora avança algumas etiquetas para medir o adesivo e o espaço. Execute uma vez após carregar um novo rolo ou quando as posições de impressão se deslocarem.',
'Calibration_Sent' => 'Calibração iniciada — a impressora avançará algumas etiquetas em branco para medi-las. Quando parar, faça uma impressão de teste.',
'Label_Printer_Dpi' => 'Resolução do cabeçote de impressão',
'Label_Printer_Dpi_Hint' => 'A maioria das impressoras de etiquetas tem 203 dpi. Não tem certeza? Use o botão "Descobrir resolução" abaixo — ele imprime a resposta.',
'Find_Resolution' => 'Descobrir resolução',
'Find_Resolution_Hint' => 'Imprime duas etiquetas, marcadas 203 e 300. A correta mostra um retângulo completo no adesivo com uma pequena margem uniforme nos quatro lados; a errada fica sem bordas ou invade o próximo adesivo.',
'Dpi_Test_Sent' => 'Duas etiquetas estão sendo impressas, marcadas 203 e 300. A correta mostra um retângulo completo com uma pequena margem uniforme nos quatro lados — defina "Resolução do cabeçote de impressão" com esse número e salve.',
'Label_Offset_X' => 'Deslocamento horizontal (mm)',
'Label_Offset_X_Hint' => 'Move a impressão para os lados no adesivo. Use quando o texto for cortado em uma das bordas laterais — ex.: 2,5 quando o adesivo branco fica centralizado em um papel de fundo mais largo. Ajuste em passos de 0,5.',
'Label_Offset_Y' => 'Deslocamento vertical (mm)',
'Label_Offset_Y_Hint' => 'Move a impressão ao longo da etiqueta. Aumente quando o topo do design estiver cortado ou faltando; diminua quando começar muito abaixo.',
'Feed_To_Tear' => 'Avançar até a borda de corte',
'Feed_To_Tear_Hint' => 'Avança a etiqueta até a barra de corte após cada trabalho. Deixe DESATIVADO se as etiquetas saírem deslocadas para baixo ou divididas entre adesivos — muitas impressoras não recuam antes da próxima etiqueta.',
