'Ord_Guide_MarkPaid_Note' => 'O Status do Pagamento exibido aqui continua registrando a escolha feita no checkout e permanece como está. A venda é o registro contábil, e é ela que alimenta seus relatórios de pagamentos e lucro. Use Mostrar Pagamentos na venda para revisar ou editar o que você informou.',
'Ord_Guide_Notes_Title' => 'Bom saber',
