'Set_Sidebar_Intro_Desc' => 'Reordene módulos, reordene itens dentro de um módulo ou arraste um item para outro módulo. Os módulos sempre permanecem no nível superior e itens não podem se tornar módulos. A organização salva se aplica a todos os usuários.',
'Set_Expand_All' => 'Expandir tudo',
'Set_Collapse_All' => 'Recolher tudo',
'Set_Group_Tag' => 'grupo',
'Set_Sidebar_Modules_Top_Only' => 'Os módulos só podem ser reordenados no nível superior.',
'Set_Sidebar_Groups_Under_Module' => 'Os grupos só podem ser colocados diretamente abaixo de um módulo.',
'Set_Sidebar_Items_Inside' => 'Os itens devem permanecer dentro de um módulo ou grupo.',
'Set_Sidebar_Reset_Confirm' => 'Restaurar a estrutura original do menu lateral para todos os usuários?',
'Set_Filter_Source' => 'Filtrar origem…',
'Set_Regenerate' => 'Gerar novamente',
'Set_Error' => 'Erro',
'Set_Zatca_Failed_Http' => 'FALHOU (HTTP {code})',
'Set_Zatca_Unit_Placeholder' => 'Filial Principal',
'Set_Zatca_Category_Placeholder' => 'Varejo',
'Set_Zatca_Exemption_Placeholder' => 'Exportação de mercadorias',
'Set_Zatca_Reported' => 'Reportado',
'Set_Zatca_Cleared' => 'Liberado',
'Set_Translations_For' => 'Traduções de {name}',
'Set_Showing_Translations' => 'Exibindo {shown} de {total} traduções',
'Set_Logout_Other_Devices' => 'Desconectar outros dispositivos',
'Set_Login_At' => 'Login',
'Set_Queue_Driver' => 'Driver',
'Set_Health_Critical_Summary' => 'Um serviço reportou um erro — ação necessária.',
'Set_Health_Warning_Summary' => 'Algumas verificações precisam de atenção (jobs com falha ou nenhum backup recente).',
'Set_Health_Ok_Summary' => 'Todos os sistemas operacionais.',
'Set_Follow_Device' => 'Seguir o dispositivo',
'Set_Returns' => 'Devoluções',
'Set_Todays_Sales' => 'Vendas de hoje',
'Set_Sort' => 'Ordenar',
'Set_Audit_Log' => 'Log de auditoria',
'Set_Qb_Synced_N_Clients' => '{n} clientes sincronizados',
'Set_Qb_Synced_N_Selected' => '{n} selecionados sincronizados',
'Set_Subscription_Reminder' => 'Lembrete de assinatura',
'Upd_Note_Code_Changes_Lost' => 'Nota 1: Se você fez alguma alteração manual no código, suas alterações serão perdidas.',
'Upd_Manual_Steps_Intro' => 'Siga estas etapas para atualizar seu aplicativo',
'Upd_Note_Permission_Only' => 'Nota 2: somente um administrador ou um usuário com a permissão "{perm}" pode atualizar o sistema',
'Upd_Manual_Step_Backup_Db' => 'Faça um backup do seu banco de dados. Acesse {backup}, clique em Gerar backup — você o encontrará em {path} — ou exporte seu banco de dados pelo PhpMyAdmin e salve-o no seu computador.',
'Upd_Manual_Step_Backup_Files' => 'Faça um backup dos seus arquivos antes de atualizar.',
'Upd_Manual_Step_Download' => 'Baixe a versão mais recente na sua conta do CodeCanyon e extraia-a.',
'Upd_Manual_Step_Remove' => 'Remova os arquivos anteriores, {except}:',
'Upd_Except' => 'exceto',
'Upd_File_Label' => 'arquivo: {name}',
'Upd_Folder_Label' => 'pasta: {name}',
'Upd_Manual_Step_Reupload' => 'Envie novamente os arquivos e pastas da nova atualização, {except} os mesmos três caminhos acima.',
'Upd_Manual_Step_Visit' => 'Acesse {url} para atualizar seu banco de dados.',
'Upd_Manual_Step_Clear_Cache' => 'Limpe completamente o cache do navegador.',
'Upd_Manual_Step_Done' => 'Pronto! Aproveite o aplicativo atualizado.',
'Upd_Note_Blank_Pages' => 'Nota: Se alguma página não carregar ou ficar em branco, certifique-se de ter limpado o cache do navegador.',
'Upd_Guide_Before_Title' => '1. Antes de atualizar',
'Upd_Guide_Before_Download' => 'Baixe o {package} do aplicativo na sua conta do CodeCanyon ({path}). Não o extraia — o atualizador precisa do ZIP exatamente como foi baixado.',
'Upd_Latest_Full_Zip' => 'pacote ZIP completo mais recente',
'Upd_Guide_Before_Admin' => 'Certifique-se de estar conectado como um administrador que tenha a permissão {perm}. Ninguém mais pode ver ou executar o atualizador.',
'Upd_Guide_Before_Quiet' => 'Escolha um momento tranquilo: durante a atualização o aplicativo entra em modo de manutenção por um curto período e os demais usuários ficam bloqueados.',
'Upd_Guide_Before_No_Manual' => 'Você {not} precisa fazer backup manualmente, extrair arquivos, executar comandos, editar arquivos de configuração ou mexer no banco de dados — o atualizador faz tudo isso automaticamente. (Um backup manual extra nunca faz mal, é claro.)',
'Upd_Not' => 'não',
'Upd_Guide_Code_Overwritten' => 'Se você modificou o código do aplicativo manualmente, suas alterações serão sobrescritas pela atualização. Seus dados, uploads, configurações e o .env são sempre preservados.',
'Upd_Guide_Running_Title' => '2. Executando a atualização',
'Upd_Guide_Run_Open' => 'Abra {path} (esta página) e permaneça na aba {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: clique ou arraste o pacote baixado para a caixa de upload. Arquivos grandes são enviados em pequenas partes, então isso também funciona em hospedagens compartilhadas com limites de upload baixos. Um checksum protege contra uploads corrompidos ou incompletos.',
'Upd_Upload_The_Zip' => 'Envie o ZIP',
'Upd_Guide_Run_Validation' => '{auto} após o upload (você pode executá-la novamente com o botão {button}). O sistema verifica: integridade do ZIP, estrutura e completude do pacote, compatibilidade de versão (downgrades são recusados), versão do PHP e extensões necessárias, permissões de arquivos, espaço livre em disco, conexão com o banco de dados, configuração e se nenhuma outra atualização está em execução.',
'Upd_Validation_Runs_Automatically' => 'A validação é executada automaticamente',
'Upd_Guide_Run_Review' => 'Revise o painel {panel}. O botão {button} só aparece quando todas as verificações críticas são aprovadas. Se uma verificação falhar, a mensagem informa exatamente o que corrigir.',
'Upd_Guide_Run_Click' => 'Clique em {button} e confirme. Depois, basta {keep} e acompanhar a barra de progresso. O sistema executa, em ordem:',
'Upd_Keep_Page_Open' => 'manter esta página aberta',
'Upd_Guide_Phase_Backup' => '{label} — um dump completo do banco de dados, um ZIP de todos os arquivos do aplicativo que a atualização pode alterar e uma cópia do {env} são criados e {verified}. Seus uploads ({images}) e {storage} nunca são alterados por uma atualização, por isso não são arquivados. Se um backup não puder ser criado, a atualização para aqui e nada é alterado.',
'Upd_Verified' => 'verificados',
'Upd_Guide_Phase_Prepare' => '{label} — a nova versão é extraída para uma área de preparação e validada novamente. O aplicativo em produção continua intocado.',
'Upd_Guide_Phase_Maintenance' => '{label} — o modo de manutenção é ativado; os visitantes veem uma tela amigável "Voltamos já".',
'Upd_Guide_Phase_Files' => '{label} — os novos arquivos são trocados quase instantaneamente; os arquivos antigos são guardados para reversão. Caminhos protegidos ({env}, {storage}, {images}) nunca são substituídos.',
'Upd_Guide_Phase_Database' => '{label} — as migrations são executadas e, em seguida, permissões, traduções e modelos são atualizados.',
'Upd_Guide_Phase_Cache' => '{label} — todos os caches são limpos e reconstruídos.',
'Upd_Guide_Phase_Verify' => '{label} — verificações de integridade confirmam que a nova versão inicia, o banco de dados funciona, todas as migrations foram executadas e a configuração é válida.',
'Upd_Guide_Phase_Done' => '{label} — o modo de manutenção é desativado e os arquivos temporários são removidos.',
'Upd_Guide_Run_Success' => 'Quando você vir {success}, clique em {reload} e force a atualização do navegador ({keys}) para que os novos recursos do painel administrativo sejam carregados.',
'Upd_Update_Successful_Short' => 'Atualização concluída com sucesso',
'Upd_Guide_No_Internet' => 'Nenhuma conexão com a internet é necessária durante a atualização — tudo vem do ZIP enviado. Perder a conexão ou fechar o navegador NÃO interrompe a atualização: o servidor lembra exatamente onde parou.',
'Upd_Guide_Wrong_Title' => '3. Se algo der errado',
'Upd_Guide_Wrong_Rollback' => '{label} — se algo falhar depois que os arquivos começaram a ser alterados (erro de extração, falha de migration, verificação de integridade com falha, disco cheio, …), o sistema restaura automaticamente os arquivos anteriores e o banco de dados a partir do backup verificado, desativa o modo de manutenção e informa {message}. Você volta exatamente ao ponto de partida.',
'Upd_Automatic_Rollback' => 'Reversão automática',
'Upd_Failed_Previous_Restored' => 'Falha na atualização — versão anterior restaurada',
'Upd_Guide_Wrong_Interrupted' => '{label} (reinício do servidor, tempo esgotado, navegador fechado, queda de energia) — ao reabrir esta página, um banner vermelho oferece duas opções seguras: {resume} (retoma exatamente da etapa onde parou) ou {rollback} (restaura a versão anterior a partir do backup).',
'Upd_Interrupted_Update' => 'Atualização interrompida',
'Upd_Guide_Wrong_Unreachable' => '{label} — use o {console} independente em {path}. Ele funciona mesmo enquanto o site está em modo de manutenção ou os recursos do painel administrativo estão com problema, e oferece as mesmas ações Continuar / Reverter. Há também um link discreto "Acesso do administrador" na parte inferior da tela de manutenção.',
'Upd_Admin_Unreachable' => 'Painel administrativo inacessível',
'Upd_Recovery_Console' => 'console de recuperação',
'Upd_Guide_Wrong_Locked_Out' => '{label} — enquanto uma atualização está em execução, esta página mostra um {link}. Salve-o caso precise entrar novamente (por exemplo, depois que sua sessão expirar); ele permite passar pela tela de manutenção para que você possa fazer login de novo.',
'Upd_Locked_Out_Maintenance' => 'Bloqueado pelo modo de manutenção',
'Upd_Bypass_Link' => 'link de acesso direto',
'Upd_Guide_Wrong_Concurrent' => '{label} — ele verá {message} Somente uma atualização pode ser executada por vez.',
'Upd_Another_Admin_Updating' => 'Outro administrador tenta atualizar ao mesmo tempo',
'Upd_Guide_Backups_Title' => '4. Backups e restauração',
'Upd_Guide_Backups_Created' => 'Toda atualização cria um backup {before} de alterar qualquer coisa: todos os arquivos do aplicativo que a atualização pode substituir, uma cópia do {env} e um dump completo do banco de dados. Uploads e {storage} nunca são modificados por uma atualização e, portanto, não fazem parte dele — mantenha seus próprios backups desses itens. Os backups ficam em {path} e nunca são acessíveis pela web.',
'Upd_Before' => 'antes',
'Upd_Guide_Backups_Panel' => 'O painel {panel} na aba {tab} os lista com data, versão e tamanho. A partir dele você pode {restore} qualquer backup completo (arquivos + banco de dados — uma cópia de segurança do banco de dados atual é feita antes) ou {delete} os antigos.',
'Upd_Restore_Verb' => 'restaurar',
'Upd_Delete_Verb' => 'excluir',
'Upd_Guide_Backups_Retention' => 'Use {keep} para escolher quantos backups são mantidos; os mais antigos são removidos automaticamente após cada atualização bem-sucedida. O único backup completo restante nunca pode ser excluído — você sempre mantém um caminho de volta.',
'Upd_Guide_Manual_Title' => '5. Atualização manual (método alternativo)',
'Upd_Guide_Manual_Text' => 'Se preferir atualizar manualmente, ou se o atualizador não puder ser usado no seu servidor, siga as instruções passo a passo na aba {tab} desta página.',
'Upd_Guide_Clear_Cache_First' => 'Se as páginas parecerem quebradas ou em branco após qualquer atualização, limpe primeiro o cache do navegador — essa é quase sempre a causa.',
'Upd_Restore_Backup_Confirm' => 'Restaurar este backup? Os arquivos atuais e o banco de dados atual serão substituídos pelo backup. Uma cópia de segurança do banco de dados atual é feita antes. (v{version} — {date})',
'Woo_Guide_Lead' => 'Como uma loja WooCommerce se mantém em sincronia com o ERP. As linhas de cron abaixo foram geradas para este servidor, então podem ser copiadas diretamente para ele.',
'Woo_Guide_Ways_Note' => 'Ao contrário do Shopify, o WooCommerce não envia nada ao ERP por conta própria — não há receptor de webhook aqui, então tudo o que {in} chega pelo agendamento. Apenas o estoque que {out} pode ser imediato.',
'Woo_In' => 'entra',
'Woo_Out' => 'sai',
'Woo_Guide_Both_Ways_Title' => 'Ambas as formas precisam disto primeiro',
'Woo_Api_Keys' => 'Chaves de API',
'Woo_Guide_Api_Keys_Text' => '{path}, permissão {perm}. Copie a consumer key e o secret para a aba {settings}, junto com a URL da loja — o endereço do seu site sem barra no final, ex.: {example}.',
'Woo_Credentials_Saved' => 'credenciais salvas',
'Woo_Not_Configured_Yet' => 'ainda não configurado',
'Woo_Guide_Wp_App_Password_Title' => 'Senha de aplicativo do WordPress (opcional)',
'Woo_Guide_Wp_App_Password_Text' => 'Usada apenas para imagens de produtos. A API do WooCommerce transfere produtos, estoque, categorias, marcas, clientes e pedidos; a API do WordPress é a que pesquisa a Biblioteca de Mídia e envia uma imagem que ainda não está lá.',
'Woo_Guide_Wp_App_Password_Note' => 'Use um usuário do WordPress que possa gerenciar mídia e crie a senha em {path}. Deixe ambos os campos em branco e tudo continua sincronizando — apenas o anexo de imagens é ignorado.',
'Woo_Guide_Pick_Way_Title' => 'Depois escolha como manter a sincronia',
'Woo_Right_Away' => 'Imediatamente',
'Woo_Stock_Live' => 'estoque em tempo real',
'Woo_Stock_Not_Live' => 'estoque não em tempo real',
'Woo_Guide_Realtime_Lead' => 'Apenas uma direção: estoque e produtos saindo do ERP. Pedidos e edições de produtos feitas no WooCommerce continuam chegando pelo agendamento — veja a outra aba.',
'Woo_Push_Stock_On_Change' => 'Enviar o estoque no momento em que mudar',
'Woo_Setting_People_Miss' => 'Esta é a configuração que as pessoas esquecem',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Uma venda no PDV {not} chega ao WooCommerce sozinha. Com isso desativado, a loja só fica sabendo na próxima sincronização de estoque — de hora em hora, por padrão — e nesse intervalo pode vender uma unidade que você já vendeu no caixa.',
'Woo_Does_Not' => 'não',
'Woo_Guide_Tick_Instant' => 'Marque {option} na aba {settings}. Essa é toda a configuração — sem worker, sem cron. Cada venda, devolução, ajuste, transferência e compra recebida passa a enviar apenas os produtos envolvidos, logo após a venda ser salva, e uma venda de vinte linhas custa um envio, não vinte. O caixa nunca espera por isso.',
'Woo_Currently' => 'Atualmente:',
'Woo_Instant_On_Text' => 'ativado — estoque enviado ao mudar',
'Woo_Instant_Off_Text' => 'desativado — estoque apenas pelo agendamento',
'Woo_Guide_Instant_Note' => 'Somente produtos já vinculados ao WooCommerce são enviados — um que nunca foi sincronizado não tem nada na loja para corrigir. Produtos variáveis passam pelo produto pai, e um combo é reenviado quando qualquer um de seus componentes muda. Operações em massa (excluir um produto, redefinir um armazém) gravam o estoque sem disparar um evento, o que é um motivo para manter também a sincronização de estoque de hora em hora.',
'Woo_Push_Products_On_Save' => 'Enviar produtos no momento em que forem salvos',
'Woo_Guide_Tick_Auto_Products' => 'Marque {option} na aba {settings} e um produto criado, editado ou duplicado no Stocky é enviado ao WooCommerce logo após ser salvo — detalhes, preço, variantes e imagens, e depois seu estoque. Um produto novo é criado na loja imediatamente, em vez de esperar pela sincronização noturna de produtos.',
'Woo_On' => 'ativado',
'Woo_Off' => 'desativado',
'Woo_Guide_Bulk_Imports_Note' => 'Importações em massa não são enviadas uma a uma — execute uma sincronização de produtos após uma importação. Sincronize categorias e marcas primeiro, para que o produto enviado caia na categoria certa.',
'Woo_Nothing_Else_To_Install' => 'Nada mais para instalar',
'Woo_Guide_Same_Process' => 'Sem worker de fila, sem entrada de cron. O envio é executado no mesmo processo que atendeu a venda, {after} a resposta ter sido devolvida, então o caixa nunca fica esperando pelo WooCommerce. Os envios nunca se sobrepõem: alterações feitas enquanto um está em execução aguardam e são enviadas logo em seguida.',
'Woo_After' => 'depois de',
'Woo_Guide_Shop_Stops_Answering' => 'Uma loja que para de responder é abandonada após oito segundos, e os envios ficam pausados por cinco minutos para que cada venda não precise esperar por ela novamente; as alterações que chegaram nesse meio-tempo saem com o primeiro envio após a pausa, e a sincronização de estoque de hora em hora recupera tudo de qualquer forma. Cada pausa é registrada na aba Logs.',
'Woo_Guide_Artisan_Exception' => 'Uma exceção: uma alteração de estoque feita por um comando artisan não tem resposta após a qual ser enviada, então ela é colocada na fila {queue}. Para que essas também sejam enviadas prontamente, processe essa fila:',
'Woo_Cron_Line_Copied' => 'Linha de cron copiada',
'Woo_Command_Copied' => 'Comando copiado',
'Woo_Guide_Not_Woo_Queue' => 'Propositalmente não é a fila {queue}: ela carrega os lotes de catálogo que duram horas, e um envio instantâneo enfileirado atrás de um deles não seria instantâneo.',
'Woo_On_A_Schedule' => 'Por agendamento',
'Woo_Guide_Scheduled_Lead' => 'Tudo é verificado novamente de tempos em tempos, nos dois sentidos. É assim que os pedidos chegam ao ERP, como um catálogo é publicado e o que corrige qualquer coisa que o caminho rápido deixou passar. Cada job tem sua própria entrada de cron, então você executa apenas o que quiser.',
'Woo_Guide_Sync_Drains_Queue' => '{command} processa sua própria fila enquanto é executado, então essas linhas não precisam de um worker separado. No Windows, use o Agendador de Tarefas com o programa {program} e os mesmos argumentos, iniciado em {path}.',
'Woo_Or_No_Cron' => 'Ou nenhum cron',
'Woo_Guide_No_Cron_Text' => 'Todas as abas aqui sincronizam sob demanda, e uma sincronização manual processa seus próprios lotes enquanto a página está aberta — então uma loja pequena pode funcionar sem nenhuma entrada de cron. O que você perde é tudo o que acontece enquanto ninguém está olhando: os pedidos só chegam quando alguém pressiona o botão.',
'Woo_Commands_Worth_Knowing' => 'Comandos úteis',
'Woo_Worth_Knowing' => 'Bom saber',
'Woo_Guide_Changing_Url_Clears' => 'Alterar a URL da loja ou as chaves de API apaga todos os mapeamentos — produtos, categorias, marcas e clientes são todos sincronizados novamente com a nova loja.',
'Woo_Guide_Keep_Skus' => 'Mantenha os SKUs consistentes entre o Stocky e o WooCommerce: é isso que evita duplicatas e torna a revinculação segura.',
'Woo_Guide_Stock_Total' => 'O estoque publicado no Woo é o {total}, não o número de um único armazém.',
'Woo_Total_Across_Warehouses' => 'total de todos os armazéns',
'Woo_Guide_Full_Reference' => 'A referência completa — todos os escopos, como a fila se comporta e uma lista de solução de problemas — está em {file}.',
'Woo_Way_Covers' => 'Abrange',
'Woo_Way_Covers_Realtime' => 'Apenas o estoque que sai do ERP — uma venda no PDV, uma devolução, um ajuste, uma compra recebida',
'Woo_Way_Covers_Scheduled' => 'Tudo, nos dois sentidos: pedidos e alterações de produtos entrando, catálogo e estoque saindo',
'Woo_Way_Speed' => 'Velocidade',
'Woo_Way_Seconds' => 'Segundos',
'Woo_Way_Speed_Scheduled' => 'O que você definir na entrada de cron (estoque de hora em hora, pedidos a cada 15 min)',
'Woo_Way_Needs' => 'Requer',
'Woo_Way_Needs_Realtime' => 'Nada — apenas a configuração',
'Woo_Way_Needs_Scheduled' => 'Uma entrada de cron por job — ou nada, se você sincronizar manualmente',
'Woo_Way_Switched_On_At' => 'Ativado em',
'Woo_Way_Cron_Entries_Below' => 'As entradas de cron abaixo',
'Woo_Cron_Orders' => 'Pedidos a cada 15 minutos — apenas os alterados desde a última execução.',
'Woo_Cron_Products_Pull' => 'Alterações de produtos da loja, todas as noites às 03:00.',
'Woo_Cron_Customers' => 'Clientes, todas as noites às 03:30.',
'Woo_Cron_Stock' => 'Estoque a cada hora — a rede de segurança sob o envio instantâneo, e a única sincronização de estoque sem ele.',
'Woo_Cron_Products_Push' => 'Produtos ainda não vinculados, todas as noites às 02:00. Produtos existentes não são reescritos.',
'Woo_Cmd_Stock' => 'Enviar agora o estoque de todos os produtos vinculados.',
'Woo_Cmd_Products_Unsynced' => 'Publicar produtos que ainda não têm ID do WooCommerce.',
'Woo_Cmd_Orders' => 'Importar pedidos alterados desde a última execução.',
'Woo_Cmd_Orders_Full' => 'Reverificar todos os pedidos em vez de apenas as alterações recentes.',
'Woo_Cmd_Pull' => 'Tudo o que entra de uma vez: produtos, pedidos, clientes.',
'Woo_Guide_Page_Title' => 'Guia do WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Conectando a loja, o que é executado sozinho e as entradas de cron para este servidor',
'Woo_Settings_Button' => 'Configurações do WooCommerce',
'Woo_No_Shop_Connected' => 'Nenhuma loja conectada ainda',
'Woo_No_Shop_Connected_Desc' => 'Tudo abaixo continua válido — informe a URL da loja e as chaves de API na página de configurações do WooCommerce e depois volte aqui.',
'Woo_Wp_Username' => 'Usuário do WordPress',
'Woo_Wp_App_Password' => 'Senha de aplicativo do WordPress',
'Woo_Settings_Instant_Hint' => 'Uma venda, devolução ou ajuste envia o estoque apenas desses produtos no instante em que é salvo, então a loja fica correta em segundos em vez de na próxima sincronização de estoque de hora em hora. Nada mais para instalar — o envio é executado depois que a venda foi respondida, então o caixa nunca espera pelo WooCommerce. Mais detalhes na aba {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Se deixar desativado, uma venda no PDV só chega ao WooCommerce na próxima sincronização de estoque — até uma hora depois.',
'Woo_Settings_Auto_Products_Hint' => 'Um produto criado, editado ou duplicado no Stocky é enviado ao WooCommerce logo após ser salvo — detalhes, preço, variantes, imagens e depois seu estoque — em vez de esperar por uma sincronização de produtos. Importações em massa não são enviadas; execute uma sincronização de produtos após uma importação.',
'Woo_Sync_Tuning' => 'Ajuste da sincronização',
'Woo_Sync_Tuning_Intro' => 'Os padrões atendem à maioria das lojas. Altere-os apenas se a sincronização estiver lenta ou exceder o tempo limite na sua hospedagem. Cada valor é limitado a um intervalo seguro, e limpar um campo restaura seu padrão.',
'Woo_Setting_This_Up' => 'Configurando',
