'Telegram_G_A_Title' => 'Imediatamente — nada para instalar',
'Telegram_G_A_Body' => 'Uma venda, compra, pagamento ou despesa salva no Stocky — no PDV ou no painel administrativo — é enviada ao Telegram {after} ser salva, na mesma requisição. Sem entrada de cron, sem worker de fila, e o operador de caixa nunca espera pelo Telegram: a venda já foi respondida quando a mensagem sai.',
'Telegram_G_Right_After' => 'logo após',
'Telegram_G_B_Title' => 'A entrada de cron — para novas tentativas e eventos em segundo plano',
'Telegram_G_B_Body' => 'Dois tipos de mensagem aguardam na própria fila do Telegram: um envio que falhou (Telegram inacessível por um momento), que é tentado novamente até mais três vezes nos minutos seguintes; e eventos gerados fora do painel administrativo — pedidos importados do WooCommerce ou do Shopify, comandos artisan. Esta entrada de cron os envia, e nada mais:',
'Telegram_G_Cron_Note' => 'A cada minuto é o ideal: uma execução sem nada pendente termina imediatamente. No cPanel isso vai em {cronJobs} — use o caminho completo para o PHP 8.2+ se o {php} for mais antigo. No Windows, use o Agendador de Tarefas com o programa {program}, argumentos {args}, iniciado em {path}.',
