'Presta_Push_Products_Desc' => 'Cria no PrestaShop os produtos simples que estão faltando (com o estoque atual). Produtos já vinculados e produtos com variantes são ignorados — continue editando os detalhes dos produtos no PrestaShop ou importe para atualizar a cópia local.',
