'Presta_Pull_Orders_Desc' => 'Importa os pedidos da loja como vendas (referências como {ref}), dos mais recentes para os mais antigos. Pedidos já importados e cancelados são ignorados, então importar regularmente é seguro. O PrestaShop não tem webhooks — execute isto após períodos de muito movimento.',
'Presta_Guide_1' => 'No back office do PrestaShop, abra {menu} e ative o webservice.',
