'Xero_Amounts_Desc' => 'As faturas usam linhas NoTax que espelham exatamente a venda (itens + frete − desconto + imposto), de modo que os totais do Xero sempre sejam iguais aos totais do Stocky. Seu contador pode remapear as linhas de imposto e frete para as contas adequadas dentro do Xero.',
