'Jumia_Prices_Stock' => 'Preços e Estoque',
'Jumia_Push_Prices_Stock_Title' => 'Enviar preços e estoque para o Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Envia o preço e a quantidade atuais de cada produto (e variante) que tenha um SKU correspondente ao {sku} do anúncio no Jumia. As atualizações são enviadas como feeds do Seller Center e aplicadas de forma assíncrona — o ID do feed é registrado na aba Registros, e as rejeições por item aparecem na tela de status de feeds do Seller Center.',
'Jumia_Push_Prices_Stock' => 'Enviar preços e estoque',
'Jumia_Pull_Orders_Desc' => 'Importa os pedidos do marketplace como vendas (referências como {ref}), associados aos seus produtos pelo Seller SKU. Pedidos já importados e cancelados são ignorados, então importar regularmente é seguro. Os pagamentos são marcados como pagos somente para pedidos entregues (o Jumia é predominantemente pagamento na entrega).',
'Jumia_Guide_1' => 'No Jumia {sellerCenter}, abra {menu} e gere uma chave de API.',
'Jumia_Guide_2' => 'Informe a URL da API do seu país (ex.: {ng} para a Nigéria, {ke} para o Quênia, {eg} para o Egito), o email da sua conta no Seller Center e a chave — depois execute {test}.',
'Jumia_Guide_3' => 'Certifique-se de que o {sku} de cada anúncio no Jumia seja igual ao código do produto no Stocky — essa é a identidade usada tanto para o envio de estoque quanto para a associação de pedidos.',
'Jumia_Guide_4' => 'Envie preços e estoque após mudanças no inventário; importe os pedidos regularmente (o Jumia não tem webhooks nesta API).',
'Jumia_Guide_5' => 'A criação de novos anúncios continua no Seller Center — o Jumia exige atributos específicos por categoria e revisão de imagens que só o portal deles trata bem.',
