'Mailchimp_Guide_1' => 'No Mailchimp, abra {menu} e crie uma chave (ela termina em {suffix} — esse sufixo é o seu datacenter).',
'Mailchimp_Guide_2' => 'Cole a chave aqui, salve, depois clique em {load} e escolha o público a ser abastecido.',
'Mailchimp_Guide_3' => 'Deixe o {doubleOptIn} ativado, a menos que seus clientes já tenham consentido em receber emails de marketing.',
