'Shopify_Hook_Note_Register' => 'O registro cria as assinaturas no Shopify e as aponta automaticamente para este endereço. Não o adicione manualmente em Shopify → Settings → Notifications → Webhooks: esses são assinados com uma chave secreta diferente e todas as entregas seriam recusadas.',
