'Shopify_Could_Not_Load_Store' => 'Não foi possível carregar esta loja',
'Shopify_G_Lead_Store' => 'O que esta loja precisa para se manter sincronizada. Tudo aqui é específico desta loja — os caminhos e IDs são reais, então os comandos podem ser copiados direto para o servidor.',
'Shopify_G_Lead_Generic' => 'Como uma loja Shopify se mantém sincronizada com o ERP. Escolha uma loja acima para ver o estado dela, ou leia assim mesmo — a linha do cron e a URL do webhook são as mesmas, qualquer que seja a loja conectada.',
'Shopify_G_Ways_Note' => 'A maioria das lojas usa as duas: a primeira mantém a loja atualizada minuto a minuto, a segunda captura o que a primeira deixou passar — um webhook que nunca chegou, uma edição feita direto no admin do Shopify, uma noite em que o site ficou fora do ar.',
'Shopify_G_Both_Need' => 'As duas formas precisam disto primeiro',
'Shopify_G_Credentials' => 'Credenciais do Shopify',
'Shopify_G_Cred_Intro' => 'Desde janeiro de 2026 o Shopify não cria mais apps personalizados dentro do admin, então existem dois tipos de conexão:',
'Shopify_G_Cred_DevDash' => '{app} (qualquer loja conectada agora) — {path}. Conceda os escopos da Admin API para o que esta loja sincroniza, instale o app na loja e copie o {clientId} e o {clientSecret} da página de configurações do app para {where}. O ERP os troca por um token de acesso por conta própria e o renova antes de expirar, a cada 24 horas. O client secret também assina os webhooks, então nada mais é necessário. O app e a loja devem estar na mesma organização do Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'App do Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (criado no admin antes de 2026) — continua funcionando sem alterações com seu {token} ({prefix}) e sua {secret} como segredo de assinatura dos webhooks. Não é o mesmo valor do token, e trocá-los é o motivo mais comum de os webhooks serem recusados.',
'Shopify_G_Legacy_App' => 'App personalizado legado',
'Shopify_G_API_Secret_Key' => 'Chave secreta da API',
'Shopify_G_Stored' => 'armazenado',
'Shopify_G_Missing_Refused' => 'ausente — as entregas serão recusadas',
'Shopify_G_Where_Data_Desc' => '{path} O armazém do ERP cujo estoque esta loja vende e a localização do Shopify onde esse estoque é gravado. A sincronização de estoque e a importação de pedidos se recusam a rodar sem eles.',
'Shopify_G_Currently' => 'Atualmente: armazém {warehouse}, localização {location}',
'Shopify_G_Not_Set_Lower' => 'não definido',
'Shopify_G_Ready' => 'pronto',
'Shopify_G_Incomplete' => 'incompleto',
'Shopify_G_Manual_Syncs' => 'Sincronizações que você inicia manualmente',
'Shopify_G_Manual_Desc' => 'Uma sincronização iniciada na {centre} responde na hora e roda em segundo plano, em pequenas etapas que continuam de onde a anterior parou. Um catálogo grande nunca é interrompido no meio por hospedagens que encerram requisições longas (LiteSpeed, nginx, um balanceador de carga), e fechar a página não a interrompe. O worker para isso é mais uma linha de cron:',
'Shopify_G_Cron_Copied' => 'Linha do cron copiada',
'Shopify_G_Manual_Note' => 'Sem ela a sincronização ainda termina, mas só enquanto a página da Central de Sincronização estiver aberta: quando nenhum worker assume uma execução em poucos segundos, a própria página a continua, uma requisição curta por vez. No Windows, use o Agendador de Tarefas a cada minuto: programa {program}, argumentos {args}, iniciar em {dir}.',
'Shopify_G_Then_Pick' => 'Depois escolha como ela se mantém sincronizada',
'Shopify_G_Right_Away' => 'Imediatamente',
'Shopify_G_Stock_Live' => 'estoque em tempo real',
'Shopify_G_Stock_Not_Live' => 'estoque não em tempo real',
'Shopify_G_Realtime_Lead' => 'Cada alteração é enviada assim que acontece, em segundos. São duas metades, com chaves separadas: os {webhooks} trazem os eventos da própria loja e o {push} envia o estoque.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'envio instantâneo de estoque',
'Shopify_G_Webhooks_In' => 'Webhooks — a loja → o ERP',
'Shopify_G_Webhooks_Desc' => 'Pedidos, mudanças de status de pedidos e edições de produtos, clientes e estoque feitas no Shopify. Abra a loja e clique em {button} na {tab} — pode clicar duas vezes sem problema. O Shopify envia para:',
'Shopify_G_Webhooks_Tab' => 'aba Webhooks',
'Shopify_G_Webhooks_Note' => 'O endereço precisa estar acessível pela internet via HTTPS — o Shopify não entrega para {localhost} nem para um domínio {test}. Cada entrega é registrada uma única vez, então as novas tentativas do Shopify não podem criar um pedido duplicado, e uma entrega com falha pode ser reprocessada. As entregas são recusadas até que o segredo de assinatura do passo 1 esteja armazenado.',
'Shopify_G_Instant_Out' => 'Envio instantâneo de estoque — o ERP → a loja',
'Shopify_G_Setting_Missed' => 'Esta é a configuração que as pessoas esquecem',
'Shopify_G_Pos_Not_Auto' => 'Uma venda no PDV {not} chega ao Shopify sozinha. Desativado, a loja só fica sabendo na próxima etapa de envio de estoque — e nesse intervalo ela pode vender uma unidade que você já vendeu no caixa.',
'Shopify_G_Not' => 'não',
'Shopify_G_Tick_Push' => 'Marque {setting} em {where}. Essa é toda a configuração — sem worker, sem cron. Cada venda, devolução e ajuste passa a enviar apenas aqueles produtos, logo após a venda ser salva, e uma venda de vinte linhas custa um envio, não vinte. O caixa nunca espera por isso.',
'Shopify_G_This_Store' => 'Esta loja:',
'Shopify_G_Push_On' => 'ativado — estoque enviado a cada alteração',
'Shopify_G_Push_Off' => 'desativado — estoque apenas pelo agendamento',
'Shopify_G_Push_Note' => 'Só são enviados os produtos que já têm um mapeamento no Shopify, e só as movimentações no armazém desta loja. Operações em massa — excluir um produto, zerar um armazém — gravam o estoque sem disparar um evento, o que é um dos motivos para manter também a etapa agendada de estoque.',
'Shopify_G_Nothing_Install' => 'Nada mais para instalar',
'Shopify_G_No_Worker_Note' => 'Nenhuma das metades precisa de um worker de fila ou de uma entrada no cron. Um webhook recebido é tratado na própria requisição que o Shopify faz; um envio de estoque roda no mesmo processo que atendeu a venda, {after} a resposta ter sido devolvida — assim o caixa nunca espera pelo Shopify, e uma loja que para de responder é abandonada após dez segundos e fica para o próximo envio agendado de estoque.',
'Shopify_G_After' => 'depois de',
'Shopify_G_Artisan_Note' => 'Uma exceção: uma alteração de estoque feita por um comando artisan não tem resposta depois da qual rodar, então ela é colocada na fila {queue}. Se quiser que essas também saiam rapidamente, processe essa fila:',
'Shopify_G_On_Schedule' => 'Por agendamento',
'Shopify_G_On_Lower' => 'ativado',
'Shopify_G_Off_Lower' => 'desativado',
'Shopify_G_Scheduled_Lead' => 'Tudo é verificado novamente de tempos em tempos, nos dois sentidos. É mais lento que o tempo real, mas é o que envia o estoque nas lojas que não usam envio instantâneo, o que captura um webhook perdido e a única forma de mover um catálogo inteiro.',
'Shopify_G_Cron_Entry' => 'A entrada do cron',
'Shopify_G_Cron_Entry_Desc' => 'Nada agendado roda sem ela. Uma linha, apenas para este módulo — adicione-a junto com o que mais você tiver escolhido agendar:',
'Shopify_G_Cron_Note' => 'A cada cinco minutos é a menor resolução que um plano pode usar, porque cinco minutos é o menor intervalo de etapa. Uma entrada mais espaçada passa a ser o mínimo — com {example}, uma etapa definida para 5 minutos roda a cada 15. No Windows, use o Agendador de Tarefas: programa {program}, argumentos {args}, iniciar em {dir}.',
'Shopify_G_Switch_On_Plan' => 'Ative e escolha o plano',
'Shopify_G_Plan_Desc' => '{where} A chave decide se o cron pode agir; o plano decide o que ele faz. Uma {step} é uma entidade em um sentido com seu próprio intervalo — {first}, {second}. O intervalo padrão é usado por qualquer etapa que deixe seu próprio campo vazio.',
'Shopify_G_Step_Lower' => 'etapa',
'Shopify_G_Plan_Note' => 'Deixe o plano vazio e a loja busca pedidos e envia estoque no intervalo padrão, que é o que a maioria das lojas quer. Pedidos são apenas de entrada: é no Shopify que o cliente faz um pedido.',
'Shopify_G_Schedule_On' => 'agendamento ativado',
'Shopify_G_Schedule_Off' => 'agendamento desativado — somente manual',
'Shopify_G_When_Step_Runs' => 'Quando uma etapa realmente roda',
'Shopify_G_When_Note' => 'Uma etapa fica pendente quando a última vez que essa mesma etapa {started} foi há mais tempo que seu intervalo, de acordo com o histórico de execuções. Assim, uma sincronização iniciada manualmente adia a próxima automática, e uma etapa que continua falhando é tentada novamente no seu intervalo, e não a cada ciclo. A Visão geral da loja mostra a última execução de cada etapa, o próximo horário previsto e o motivo do bloqueio, quando houver. Faça o primeiro envio do catálogo manualmente — primeiro com {dryRun} — antes de colocá-lo em um agendamento.',
'Shopify_G_Started_Lower' => 'foi iniciada',
'Shopify_G_Where_Setting' => 'Onde fica cada configuração',
'Shopify_G_Where_Setting_Note' => 'Todas ficam em uma loja existente: {path}, depois o lápis (ou {edit} na própria página da loja).',
'Shopify_G_Product_Images' => 'Imagens de produtos',
'Shopify_G_Img_1' => 'As imagens são enviadas junto com o produto em um {push} — primeiro a imagem principal, depois a galeria, depois uma por variante que tenha a sua própria, até cinquenta.',
'Shopify_G_Products_Push' => 'envio de produtos',
'Shopify_G_Img_2' => 'A imagem de uma variante é enviada com o produto e depois {assigned}, que é como o Shopify a modela: uma variante aponta para uma das imagens do produto. Uma variante que reutiliza a imagem principal não a envia duas vezes.',
'Shopify_G_Assigned' => 'atribuída a essa variante',
'Shopify_G_Img_3' => 'Uma imagem armazenada como arquivo é {uploaded} para o Shopify, não vinculada, então funciona mesmo quando esta instalação não está acessível pela internet. Uma imagem adicionada como link colado é passada ao Shopify como essa URL, que precisa ser publicamente acessível.',
'Shopify_G_Uploaded' => 'enviada',
'Shopify_G_Img_4' => 'Elas só são reenviadas quando realmente mudam — um envio que altera apenas um preço não mexe nas imagens da loja, porque enviá-las substitui o conjunto inteiro.',
'Shopify_G_Img_5' => 'Remover uma imagem no ERP {not} a exclui no Shopify. Exclua lá também, ou a loja continuará exibindo-a.',
'Shopify_G_Commands' => 'Comandos úteis',
'Shopify_G_Command_Copied' => 'Comando copiado',
'Shopify_G_Foot' => 'Toda sincronização grava em {logs}, e a Visão geral de cada loja mostra quando cada etapa rodou pela última vez, quando está prevista a próxima e o que a está bloqueando, se houver algo. É ali que você deve olhar primeiro quando uma sincronização não fez o que você esperava.',
'Shopify_G_Covers' => 'Abrange',
'Shopify_G_Covers_Rt' => 'Pedidos e edições feitos no Shopify; estoque saindo do ERP (uma venda no PDV, uma devolução, um ajuste)',
'Shopify_G_Covers_Sch' => 'Tudo, nos dois sentidos — incluindo envios de catálogo e qualquer coisa que o caminho rápido deixou passar',
'Shopify_G_Speed' => 'Velocidade',
'Shopify_G_Speed_Rt' => 'Segundos',
'Shopify_G_Speed_Sch' => 'O intervalo da etapa (5 minutos a 7 dias)',
'Shopify_G_Needs' => 'Requer',
'Shopify_G_Needs_Rt' => 'Um endereço HTTPS público e o segredo de assinatura para os webhooks recebidos. O estoque enviado não requer nada',
'Shopify_G_Needs_Sch' => 'Uma entrada no cron executando {cmd}',
