'StoreAdm_PG_Intro_Desc' => 'As chaves do Stripe são compartilhadas globalmente (o admin e a loja online usam a mesma integração com o Stripe). Cada aba ativa ou desativa seu método no checkout da loja online; Pagamentos offline reúne os métodos pagos fora do sistema.',
