'StoreAdm_PG_Paypal_Webhook_Hint' => 'Garantia para pagamentos cujo redirecionamento do navegador nunca chega, além de reembolsos/estornos. Registre um webhook em {site} apontando para a URL abaixo (eventos: {events}) e cole o Webhook ID aqui.',
