'StoreAdm_PG_Paystack_Test_Live' => 'Teste ou produção é definido pelo par de chaves: chaves {test} rodam em modo de teste, chaves {live} cobram cartões reais — não há uma chave de sandbox separada.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL do webhook (garantia opcional — defina em Settings → API Keys & Webhooks no painel do Paystack; as requisições são verificadas por HMAC com sua chave secreta):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Ative o Paystack e informe suas chaves pública e secreta (de {site} → Settings → API Keys) para aceitar cartões, transferências bancárias e mobile money no checkout da loja online.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhooks, opcional)',
