'StoreAdm_PG_Flutterwave_Info' => 'Usa a API v3 do Flutterwave com chaves clássicas. Teste ou produção é definido pelo par de chaves ({keys} vs chaves de produção) — não há uma chave de sandbox separada. A moeda da loja precisa estar habilitada na sua conta Flutterwave.',
