'Cr_Guide_Step_Book_Help' => 'Na lista de vendas, abra o menu de uma venda e escolha Enviar para transportadora, ou marque várias vendas e envie todas de uma vez.',
'Cr_Guide_Step_Errors' => 'Acompanhar os erros',
'Cr_Guide_Step_Errors_Help' => 'Nenhum erro de transportadora nas últimas 24 horas.',
