'Cr_Guide_How_It_Works' => 'Como funciona',
'Cr_Guide_Meaning' => 'Significado',
'Cr_Guide_T_Statuses' => 'Status',
'Cr_Guide_Statuses_Note' => 'Os status só avançam, então uma atualização atrasada nunca faz um volume voltar atrás. Um volume entregue ainda pode ser informado como em devolução ou devolvido.',
'Cr_Guide_S_booked' => 'A transportadora recebeu o pedido; ninguém fez a coleta ainda. Só é possível cancelar a contratação nesta etapa.',
'Cr_Guide_S_picked_up' => 'A transportadora coletou o volume.',
'Cr_Guide_S_in_transit' => 'Em trânsito entre centros de distribuição, na alfândega ou retido.',
'Cr_Guide_S_out_for_delivery' => 'Com o entregador hoje.',
'Cr_Guide_S_failed_attempt' => 'Destinatário ausente, recusado ou endereço errado. A transportadora tenta novamente ou devolve.',
'Cr_Guide_S_delivered' => 'Entregue ao cliente. Um valor de COD passa a constar como recebido pela transportadora.',
'Cr_Guide_S_returning' => 'A caminho de volta para você.',
'Cr_Guide_S_returned' => 'De volta com você: aguarda em Devoluções para revisão, ou é reposto no estoque automaticamente.',
'Cr_Guide_S_cancelled' => 'A contratação foi cancelada.',
'Cr_Guide_T_Booking' => 'Contratação de envios',
'Cr_Guide_B_Booking' => 'Enviar para transportadora preenche o formulário a partir da venda: destinatário, endereço, o valor ainda em aberto como COD e o peso dos produtos. Transportadoras com listas de cidades próprias exibem um seletor, e sua escolha é memorizada para aquela cidade. Agregadores, DHL, FedEx, UPS e Lalamove oferecem Comparar tarifas: escolha um preço e Contratar o adquire. Várias vendas podem ser contratadas de uma vez pela lista de vendas.',
'Cr_Guide_T_Cod' => 'Pagamento na entrega',
'Cr_Guide_B_Cod' => 'Um volume COD passa de Não recebido para Recebido pela transportadora (na entrega) e depois para Repassado a você. Transportadoras que informam repasses avançam a última etapa sozinhas; para as demais, use Atualizar COD. Com uma conta escolhida em Configurações de transportadoras, o repasse é lançado como pagamento na venda. As taxas da transportadora podem ser salvas como despesa depois que o volume é finalizado.',
'Cr_Guide_T_Returns' => 'Volumes devolvidos',
'Cr_Guide_B_Returns' => 'Por padrão, um volume devolvido aguarda em Envios por transportadora, em Devoluções para revisar. Repor no estoque cria uma devolução de venda para o pedido inteiro e devolve os itens ao estoque; Descartar não devolve nada, para volumes danificados ou extraviados. As Configurações de transportadoras podem repor no estoque automaticamente.',
'Cr_Guide_T_Customers' => 'Mensagens ao cliente e página de rastreamento',
'Cr_Guide_B_Customers' => 'As notificações ao cliente em Configurações de transportadoras enviam SMS, email ou WhatsApp nos status que você marcar, uma vez por volume, com o seu próprio texto. A página de rastreamento na sua loja online permite que os clientes acompanhem um volume pelo código de rastreamento, ou pelo número do pedido e telefone. Clientes que devolvem volumes com frequência recebem um selo de risco de devolução quando você contrata o envio.',
'Cr_Guide_T_Labels' => 'Etiquetas',
'Cr_Guide_B_Labels' => 'Imprimir etiqueta gera a etiqueta da própria transportadora quando ela emite uma (um PDF, um link ou uma imagem); caso contrário, uma etiqueta Stocky com o código de barras de rastreamento e o valor a receber. Permita pop-ups para este site para imprimir. DHL, FedEx e UPS fornecem a etiqueta apenas uma vez, na contratação, e o Stocky a guarda para reimpressões.',
'Cr_Guide_T_Faq' => 'Solução de problemas',
'Cr_Guide_Q_Test' => 'O teste de conexão falha',
'Cr_Guide_A_Test' => 'Chaves de teste funcionam com o modo Teste e chaves de produção com o modo Produção; elas são diferentes. Abra os Logs de transportadoras e leia a resposta da transportadora para ver o motivo exato.',
'Cr_Guide_Q_City' => 'A transportadora rejeita a cidade ou o endereço',
'Cr_Guide_A_City' => 'Escolha a cidade na lista de cidades da transportadora no formulário de contratação; as transportadoras só aceitam os nomes delas. Transportadoras que trabalham com endereços postais também precisam do estado, CEP e país com duas letras.',
'Cr_Guide_Q_Webhook' => 'Os status não mudam sozinhos',
'Cr_Guide_A_Webhook' => 'Para transportadoras que enviam atualizações, verifique se a URL do webhook está registrada na transportadora: os Logs de transportadoras mostram cada atualização recebida, ou por que foi rejeitada (por exemplo, um segredo errado). As demais transportadoras são verificadas conforme o agendamento em Configurações de transportadoras, e Verificar status agora consulta na hora.',
'Cr_Guide_Q_Stuck' => 'Um envio mostra um erro de verificação de status',
'Cr_Guide_A_Stuck' => 'A transportadora recusou as últimas verificações; o motivo está no envio e nos Logs de transportadoras. Após falhas repetidas, o envio deixa de ser verificado automaticamente: corrija a causa e use Verificar status agora.',
'Cr_Guide_Q_Label' => 'Nada abre ao imprimir uma etiqueta',
'Cr_Guide_A_Label' => 'Seu navegador bloqueou o pop-up. Permita pop-ups para este site e tente novamente.',
'Cr_Guide_Q_Cod' => 'Um repasse de COD não foi lançado na venda',
'Cr_Guide_A_Cod' => 'Em Configurações de transportadoras, o pagamento na entrega precisa estar ativado e com uma conta escolhida. Sem uma conta, os repasses são apenas marcados como repassados.',
