'Tfa_Codes_Save' => 'Guarde estes códigos de recuperação em um lugar seguro. Cada um permite entrar uma vez caso você perca o celular. Eles não serão exibidos novamente.',
'Tfa_Reset' => 'Redefinir dois fatores',
'Tfa_Reset_Title' => 'Redefinir a autenticação de dois fatores?',
'Tfa_Reset_Help' => ':name entrará apenas com a senha e poderá configurar o aplicativo autenticador novamente. Faça isso somente após confirmar quem está solicitando.',
'Tfa_Guide_Lead' => 'A autenticação de dois fatores (2FA) adiciona uma segunda etapa ao login: após a senha, a equipe digita um código de 6 dígitos de um aplicativo autenticador no celular. Uma senha roubada ou adivinhada deixa de ser suficiente para entrar.',
'Tfa_Guide_State_Required' => 'Obrigatória',
'Tfa_Guide_State_Optional' => 'Não — opcional para todos',
'Tfa_Guide_State_Trust' => 'Dispositivos confiáveis',
'Tfa_Guide_State_Users' => 'Usuários com 2FA ativada',
'Tfa_Guide_Staff_Title' => 'Para cada membro da equipe',
'Tfa_Guide_App_Title' => 'Instale um aplicativo autenticador',
'Tfa_Guide_App_Text' => 'Qualquer aplicativo compatível com códigos padrão de 6 dígitos (TOTP) funciona. Eles são gratuitos e funcionam offline:',
'Tfa_Guide_Enable_Title' => 'Ative pelo perfil',
'Tfa_Guide_Enable_1' => 'Abra o Perfil (menu do avatar no canto superior direito) e encontre o cartão "Autenticação de dois fatores".',
'Tfa_Guide_Enable_2' => 'Clique em "Ativar" e confirme com a senha atual.',
'Tfa_Guide_Enable_3' => 'Escaneie o QR code com o aplicativo, ou digite a chave exibida abaixo dele.',
'Tfa_Guide_Enable_4' => 'Digite o código de 6 dígitos exibido no aplicativo para concluir.',
'Tfa_Guide_Open_Profile' => 'Abrir meu perfil',
'Tfa_Guide_Codes_Title' => 'Guarde os códigos de recuperação',
'Tfa_Guide_Codes_Text' => 'Logo após a configuração, 8 códigos de recuperação são exibidos uma única vez. Cada um substitui um código do celular uma única vez — para um celular perdido, quebrado ou redefinido. Baixe ou copie os códigos e guarde-os em um lugar seguro, longe do celular.',
'Tfa_Guide_Codes_Note' => 'Restam poucos? "Novos códigos de recuperação" no perfil substitui o conjunto inteiro; os antigos deixam de funcionar.',
'Tfa_Guide_Signin_Title' => 'Como entrar',
'Tfa_Guide_Signin_Text' => 'Após o email e a senha, a página de login pede o código atual do aplicativo. Os códigos mudam a cada 30 segundos e cada um funciona uma única vez.',
'Tfa_Guide_Signin_Trust' => 'Marcar "Não perguntar novamente neste dispositivo" dispensa o código naquele navegador por :days dias.',
'Tfa_Guide_Signin_Recovery' => 'Sem o celular em mãos? Clique em "Usar um código de recuperação" e digite um dos códigos guardados.',
'Tfa_Guide_Admin_Title' => 'Para administradores',
'Tfa_Guide_Require_Title' => 'Torne obrigatória',
'Tfa_Guide_Require_Text' => 'Ative "Exigir autenticação de dois fatores" neste cartão e escolha as funções que devem usá-la — ou deixe a lista vazia para todos os usuários. Clique em Enviar para salvar.',
'Tfa_Guide_Require_Next' => 'Ninguém é desconectado. Usuários que ainda não têm 2FA são guiados pela configuração na página de login no próximo acesso, antes de entrar, e veem seus códigos de recuperação ali.',
'Tfa_Guide_Require_Note' => 'Usuários para quem ela é obrigatória não podem desativá-la pelo perfil.',
'Tfa_Guide_Trust_Title' => 'Dispositivos confiáveis',
'Tfa_Guide_Trust_Text' => '"Lembrar dispositivos confiáveis" define por quanto tempo um navegador pode dispensar o código após um login bem-sucedido. Escolha "Sempre pedir um código" para computadores compartilhados ou públicos, como um PDV no salão da loja.',
'Tfa_Guide_Trust_Note' => 'Reduzir o número encurta o prazo dos dispositivos já confiáveis; desativar ou redefinir a 2FA esquece todos eles.',
'Tfa_Guide_Lost_Title' => 'Celular perdido e sem códigos de recuperação',
'Tfa_Guide_Lost_Text' => 'Na página Usuários, usuários com 2FA mostram "Ativada" na coluna 2FA. O botão de escudo em Ações a redefine: o usuário entra apenas com a senha e configura o aplicativo novamente (ou é solicitado a fazê-lo, se for obrigatória).',
'Tfa_Guide_Lost_Warn' => 'Confirme quem está solicitando antes de redefinir — a redefinição remove a proteção que a 2FA dá àquela conta.',
'Tfa_Guide_Open_Users' => 'Abrir Usuários',
'Tfa_Guide_Mobile_Title' => 'Aplicativo móvel e API',
'Tfa_Guide_Mobile_Text' => 'O aplicativo móvel e o endpoint de token da API pedem o mesmo código. Se a 2FA for obrigatória para um usuário que ainda não a configurou, ele precisa entrar pela web uma vez para fazê-lo.',
'Tfa_Guide_Protect_Title' => 'Proteção integrada',
'Tfa_Guide_Protect_1' => '5 códigos errados bloqueiam a digitação de códigos para aquele usuário por 15 minutos, independentemente das configurações de bloqueio acima.',
'Tfa_Guide_Protect_2' => 'Cada código e cada código de recuperação funcionam uma única vez.',
'Tfa_Guide_Protect_3' => 'Com "Registrar atividade de login" ativado, os códigos errados aparecem na lista Atividade de login como "Código 2FA incorreto".',
'Tfa_Guide_Trouble_Title' => 'Solução de problemas',
'Tfa_Guide_Faq_Clock_Q' => '“Esse código não é válido” com um código novo',
'Tfa_Guide_Faq_Clock_A' => 'Provavelmente o relógio do celular está errado. Os códigos dependem da hora: defina a data e a hora do celular como automáticas (hora da rede) e tente o próximo código.',
'Tfa_Guide_Faq_Phone_Q' => 'Mudança para um novo celular',
'Tfa_Guide_Faq_Phone_A' => 'Use o recurso de transferência do próprio aplicativo autenticador, ou desative a 2FA no perfil e ative-a novamente com o novo celular (se for obrigatória, peça a um administrador para redefini-la).',
'Tfa_Guide_Faq_Locked_Q' => '“Códigos inválidos demais”',
'Tfa_Guide_Faq_Locked_A' => 'Aguarde o tempo exibido (até 15 minutos), ou peça a um administrador para redefinir a 2FA do usuário.',
'Tfa_Guide_Faq_Key_Q' => 'Ninguém com 2FA consegue entrar após uma mudança de servidor',
'Tfa_Guide_Faq_Key_A' => 'Os segredos da 2FA são criptografados com a APP_KEY do arquivo .env. Mantenha a mesma APP_KEY ao mover ou restaurar o aplicativo; se ela mudou, um administrador sem 2FA precisa redefinir os usuários afetados.',
'Tfa_Guide_Button' => 'Guia',
