'Tfa_Guide_Rollout_Title' => 'Implante para todos os usuários',
'Tfa_Guide_Rollout_1' => 'Ative primeiro na sua própria conta (Perfil), para conhecer as etapas.',
'Tfa_Guide_Rollout_2' => 'Informe à equipe qual aplicativo instalar e que a configuração leva um minuto no login.',
'Tfa_Guide_Rollout_3' => 'Ative "Exigir autenticação de dois fatores", deixe "Obrigatória para" vazio (= todos os usuários) e, se quiser, escolha um período de carência. Clique em Enviar.',
'Tfa_Guide_Rollout_4' => 'Clique em "Desconectar usuários sem 2FA" para que quem já está conectado a configure agora, e não em algum login futuro. Você continua conectado.',
'Tfa_Guide_Rollout_5' => 'Acompanhe o progresso pelo contador neste cartão, ou pelo filtro "Precisa configurar" na página Usuários.',
'Tfa_Guide_Rollout_Note' => 'Com um período de carência, a tela de configuração exibe “Lembrar mais tarde” até o prazo; depois dele, a configuração é obrigatória para entrar.',
'Tfa_Guide_Customers_Title' => 'Contas de clientes (loja e portal do cliente)',
'Tfa_Guide_Customers_Text' => 'Os clientes também podem proteger suas próprias contas. É opcional para cada cliente e nunca imposto: ative em Configurações da loja → Controle de acesso ao cadastro (loja online) e Portal do cliente → Configurações do portal (portal do cliente).',
'Tfa_Guide_Customers_1' => 'Os clientes ativam em Minha conta (loja) ou Perfil (portal).',
'Tfa_Guide_Customers_2' => 'Eles escolhem um código enviado por email — mais fácil, sem aplicativo — ou um aplicativo autenticador com códigos de recuperação.',
'Tfa_Guide_Customers_3' => 'Os códigos por email exigem configurações de email funcionando (Configurações → Configurações de email). Eles expiram após 10 minutos.',
'Tfa_Guide_Customers_4' => 'Desativar a opção depois impede novas configurações; os clientes que já a usam continuam sendo solicitados e podem desativá-la por conta própria.',
'Tfa_Required_Grace_Notice' => 'Seu administrador exige autenticação de dois fatores. Você pode adiá-la no login até :date; depois disso, a configuração é obrigatória.',
